style.css:
/* 字体相关设置 */
body {
    /* 设置字体粗细、样式和阴影，通过body选择器应用到页面主体内容，避免过度使用通配符* */
    font-weight: 500;
    font-family: "Microsoft YaHei UI", sans-serif;
    text-shadow: 0.01em 0.01em 0.01em #999999;
}

/* 滚动条样式 */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

::-webkit-scrollbar-track-piece {
    background-color: #CCCCCC;
    border-radius: 6px;
}

::-webkit-scrollbar-thumb:vertical {
    height: 5px;
    background-color: #999999;
    border-radius: 6px;
}

::-webkit-scrollbar-thumb:horizontal {
    width: 5px;
    background-color: #CCCCCC;
    border-radius: 6px;
}

::-webkit-scrollbar {
    width: 9px;
    height: 9px;
}

::-webkit-scrollbar-track-piece {
    background-color: transparent;
}

::-webkit-scrollbar-track-piece:no-button {}

::-webkit-scrollbar-thumb {
    background-color: #3994EF;
    border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
    background-color: #A4EEF0;
}

::-webkit-scrollbar-thumb:active {
    background-color: #666;
}

::-webkit-scrollbar-button:vertical {
    width: 9px;
}

::-webkit-scrollbar-button:horizontal {
    width: 9px;
}

::-webkit-scrollbar-button:vertical:start:decrement {
    background-color: white;
}

::-webkit-scrollbar-button:vertical:end:increment {
    background-color: white;
}

::-webkit-scrollbar-button:horizontal:start:decrement {
    background-color: white;
}

::-webkit-scrollbar-button:horizontal:end:increment {
    background-color: white;
}

body::-webkit-scrollbar-track-piece {
    background-color: white;
}

/* 输入框美化 */
input,
textarea {
    border: 1px solid #ccc;
    border-radius: 6px;
}

input[type='text']:focus,
input[type='password']:focus,
textarea:focus {
    border: 2px solid #6FA1D9;
    box-shadow: 0px 0px 5px #6FA1D9;
    outline: none;
}

input[type='checkbox']:focus,
input[type='submit']:focus,
input[type='reset']:focus,
input[type='radio']:focus {
    border: 1px solid #6FA1D9;
    outline: none;
}

input:focus,
select:focus,
textarea:focus {
    outline: 1px solid #10bae0;
    border-radius: 3px;
}

/* 链接相关样式 */
a {
    text-decoration: none;
}

body *:focus {
    outline: 2px solid rgba(16, 186, 224, 0.5);
    outline-offset: 1px;
    border-radius: 2px;
}

body a:focus {
    outline-offset: 0px;
}

body button:focus,
body input[type=reset]:focus,
body input[type=button]:focus,
body input[type=submit]:focus {
    border-radius: 2px;
}

body textarea:focus,
body button:focus,
body select:focus,
body input:focus {
    outline-offset: -1px;
}

*::-webkit-selection {
    background: #333333;
    color: #00FF00;
}
